package lab.stridelab;
import android.Manifest;import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.content.Intent;import android.net.Uri;import android.database.Cursor;import android.provider.OpenableColumns;import android.provider.DocumentsContract;import android.content.Context;import android.content.pm.PackageManager;import android.location.Location;import android.location.Geocoder;import android.location.Address;import org.json.JSONArray;import org.json.JSONObject;import java.util.List;import java.util.concurrent.Executors;import java.util.concurrent.ExecutorService;import android.location.LocationManager;import android.location.LocationListener;import android.webkit.*;import android.util.Base64;import android.widget.Toast;import android.view.View;import android.view.WindowInsets;import android.os.Build;import java.io.OutputStream;import java.util.Locale;
public class MainActivity extends Activity {
 private final ExecutorService placeSearch=Executors.newSingleThreadExecutor();private byte[] pending;private String pendingName;private WebView view;private LocationManager lm;private LocationListener listener;private final Handler handler=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle state){super.onCreate(state);view=new WebView(this);android.widget.FrameLayout content=new android.widget.FrameLayout(this);content.addView(view,new android.widget.FrameLayout.LayoutParams(-1,-1));setContentView(content);if(Build.VERSION.SDK_INT>=35){content.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());v.setPadding(b.left,b.top,b.right,b.bottom);return insets;});content.requestApplyInsets();} WebSettings settings=view.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setUserAgentString(settings.getUserAgentString()+" StrideLab/0.1.0 (reference-map)");view.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});view.addJavascriptInterface(new Bridge(),"StrideAndroid");view.loadUrl("file:///android_asset/index.html");}
 public final class Bridge { @JavascriptInterface public void save(String name,String mime,String data){runOnUiThread(()->{try{if(pending!=null){toast("请先完成当前导出");return;}if(data.length()>40000000)throw new Exception("文件过大");pending=Base64.decode(data,Base64.DEFAULT);pendingName=name.replace('/','_').replace((char)92,'_');Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(pendingName.toLowerCase(Locale.ROOT).endsWith(".fit")?"application/vnd.ant.fit":mime);i.putExtra(Intent.EXTRA_TITLE,pendingName);startActivityForResult(i,101);}catch(Exception e){pending=null;pendingName=null;exportStatus(false,"无法开始导出");}});} @JavascriptInterface public void searchPlace(String query,int requestId){if(query==null||query.trim().isEmpty()||query.length()>200)return;placeSearch.execute(()->{JSONArray results=new JSONArray();try{if(Geocoder.isPresent()){List<Address> matches=new Geocoder(MainActivity.this,Locale.SIMPLIFIED_CHINESE).getFromLocationName(query.trim(),8);if(matches!=null)for(Address a:matches){if(!a.hasLatitude()||!a.hasLongitude())continue;JSONObject row=new JSONObject();String label=a.getMaxAddressLineIndex()>=0?a.getAddressLine(0):a.getFeatureName();row.put("label",label==null?query:label);row.put("lat",a.getLatitude());row.put("lon",a.getLongitude());results.put(row);}}}catch(Exception ignored){}String payload=results.toString().replace("\u2028","\\u2028").replace("\u2029","\\u2029");runOnUiThread(()->{if(!isDestroyed()&&view!=null)view.evaluateJavascript("window.StrideMapSearchResults&&window.StrideMapSearchResults("+requestId+","+payload+")",null);});});} @JavascriptInterface public void locate(){runOnUiThread(()->{if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},102);}else requestLocation();});} }
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void exportStatus(boolean ok,String message){toast(message);if(view!=null&&!isDestroyed())view.evaluateJavascript("window.StrideExportStatus&&window.StrideExportStatus("+ok+","+JSONObject.quote(message)+")",null);}
 private String documentName(Uri uri){try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())return cursor.getString(0);}catch(Exception ignored){}return null;}
 private Uri ensureFitExtension(Uri uri,String actual){if(actual==null||actual.toLowerCase(Locale.ROOT).endsWith(".fit"))return uri;String lower=actual.toLowerCase(Locale.ROOT);String target=lower.endsWith(".bin")?actual.substring(0,actual.length()-4):actual;if(!target.toLowerCase(Locale.ROOT).endsWith(".fit"))target+=".fit";try{Uri renamed=DocumentsContract.renameDocument(getContentResolver(),uri,target);if(renamed!=null)return renamed;}catch(Exception ignored){}return uri;}
 private void cancelLocation(){if(lm!=null&&listener!=null)try{lm.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
 private void locationError(){cancelLocation();view.evaluateJavascript("window.StrideMapLocationError&&window.StrideMapLocationError()",null);}
 private void locationResult(Location l){cancelLocation();view.evaluateJavascript(String.format(Locale.US,"window.StrideMapLocation&&window.StrideMapLocation(%.8f,%.8f,%.2f)",l.getLatitude(),l.getLongitude(),l.hasAccuracy()?l.getAccuracy():-1f),null);}
 @SuppressWarnings("MissingPermission") private void requestLocation(){cancelLocation();try{lm=(LocationManager)getSystemService(Context.LOCATION_SERVICE);boolean fine=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;String provider=fine&&lm.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER;if(!lm.isProviderEnabled(provider)){locationError();return;}Location last=lm.getLastKnownLocation(provider);if(last!=null&&System.currentTimeMillis()-last.getTime()<120000){locationResult(last);return;}listener=new LocationListener(){public void onLocationChanged(Location l){locationResult(l);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){locationError();}public void onStatusChanged(String p,int s,Bundle e){}};final LocationListener req=listener;lm.requestLocationUpdates(provider,1000,0,listener,Looper.getMainLooper());handler.postDelayed(()->{if(listener==req)locationError();},15000);}catch(Exception e){locationError();}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==102){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED)requestLocation();else locationError();}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=101)return;try{
 if(result!=RESULT_OK){exportStatus(false,"已取消保存");return;}
 if(data==null||data.getData()==null||pending==null||pendingName==null){exportStatus(false,"未保存：文件数据或保存位置不可用");return;}
 Uri uri=data.getData();boolean fit=pendingName.toLowerCase(Locale.ROOT).endsWith(".fit");
 if(fit){if(pending.length<14||pending[8]!=46||pending[9]!=70||pending[10]!=73||pending[11]!=84)throw new Exception("FIT header");uri=ensureFitExtension(uri,documentName(uri));}
 try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new Exception("No stream");out.write(pending);}
 String actual=documentName(uri);
 if(fit&&(actual==null||!actual.toLowerCase(Locale.ROOT).endsWith(".fit"))){exportStatus(false,"数据已写入，但保存位置未确认 .fit 后缀："+(actual==null?"名称未知":actual)+"。请换用其他文件夹重试。");}
 else exportStatus(true,"已保存："+(actual==null?pendingName:actual));
 }catch(Exception e){exportStatus(false,"保存失败，请重新导出并选择其他保存位置");}finally{pending=null;pendingName=null;}}
 @Override public void onBackPressed(){if(view==null){super.onBackPressed();return;}view.evaluateJavascript("window.StrideHandleBack&&window.StrideHandleBack()",value->{if(!"true".equals(value))super.onBackPressed();});}
 @Override protected void onStop(){if(listener!=null)locationError();super.onStop();} @Override protected void onDestroy(){cancelLocation();placeSearch.shutdownNow();handler.removeCallbacksAndMessages(null);if(view!=null){view.removeJavascriptInterface("StrideAndroid");view.destroy();}super.onDestroy();}
}
